SELECT COUNT(*) AS urun_sayisi
FROM products
WHERE product_weight_g > 10000;

SELECT COUNT(*) AS yorum_metni_yazilmis_degerlendirmeler
FROM order_reviews
WHERE review_comment_message != '';

SELECT AVG(EXTRACT(EPOCH FROM order_approved_at - order_purchase_timestamp) / 3600) AS saat
FROM orders
WHERE order_status = 'delivered' AND order_approved_at IS NOT NULL;

SELECT 100.0 * AVG(CASE WHEN order_delivered_customer_date < order_estimated_delivery_date THEN 1 ELSE 0 END) AS yuzde
FROM orders
WHERE order_status = 'delivered' AND order_delivered_customer_date IS NOT NULL;
